// ptseq.js — POINTS PHOTO DU PLAN D'ENSEMBLE (20/10/2026, lot PA). Ethan : « purge, vidange, vanne, sous-station, ça doit être des points sur lesquels on peut prendre
// des photos, plusieurs fois … les vannes pré-isolées : pouvoir spécifier ouverte ou fermée, avec date de dernière mise à jour et photo ».
// Un POINT = une pièce du tracé qui se contrôle ou se manœuvre : vanne (valve), té de purge / de vidange (tee vertical), sous-station (endpoint sousstation),
// raccordement (endpoint : PEC, insertion, attente, chaufferie), by-pass (bypass) — et toute pièce que l'encadrement décide de suivre (« Suivre ce point »).
// Clé stable d'un point : <idLigne>|<nature>@<PK à 0,1 m> (les pièces du traceur n'ont pas de uid et l'uid du moteur DXF est un simple rang : le PK est ce qu'il y a de
// plus stable ; un constat dont le PK a bougé de moins d'un mètre après un tracé refait est rapproché de la pièce, sinon il reste consultable « pièce absente du tracé »).
// Données : registre « pteq », UNE LIGNE PAR CONSTAT (deux téléphones sur le même point ne s'écrasent jamais) — id <siteId>|<cléPoint>|<uid>, data {site, pt, nature,
// ligne, ligneNom, pk, dn, label, ctx, etat, photos:[{u,w,h}], note, by, byKey, byName, at, deleted}. État courant du point = le constat le plus récent qui porte un etat.
// Photos : compressPhoto ≤ 1 280 px ; hors connexion le constat reste sur l'appareil avec ses photos en data: (file « trace:pteqUp »), envoyé au stockage puis au registre
// dès que le réseau revient (pump). Le registre ne sait charger qu'un kind entier : « pteq » de tous les chantiers est en mémoire (quelques centaines d'octets par constat,
// les photos sont des adresses), filtré par site à la lecture.
// 20/10 (suite PH, Ethan : « ce qui est vannes de sectionnement doit ressortir aussi sur l'onglet Hydro ; … sur le mode opératoire de rinçage, dire : on ouvre celle-là,
// on fait cette partie, puis on ferme ici… ») : bloc « Vannes de sectionnement » et « Mode opératoire » dans l'onglet Hydraulique (hydro.js reste pur) ; le mode
// opératoire (les ÉTAPES, composées par l'encadrement) vit dans NET.hydro.modop = {<prestation>: [{id, type, pt, tron, op, label, note}]} (enregistré par saveHydro,
// partie « hydro » = chef / bureau sur le serveur) ; le « ✓ Fait » du terrain est une ligne du registre pteq (champ step = id de l'étape : pour une vanne c'est le constat
// d'état lui-même, pour une opération / note une ligne ctx 'modop') — tout compte actif, hors connexion, une ligne par coche, jamais écrasée. Un chantier sans modop ne change pas.
import {regAll,regGet,regSet,regLoad,onReg,onRegSent,regMissing,regPending} from './reg.js';
import {PREST_LABEL} from './hydro.js'; // 20/10 (suite PH) : libellés des prestations hydrauliques (module pur)
import {docHTML} from './charte.js'; // impression du mode opératoire (charte SCR)
let A=null; // API fournie par app.js (state, net, esc, toast, plan, fiche, droits, photos…)
const CTX=[['penetration','Pénétration','🧱'],['pose','Pièce posée','🧩'],['ouverte','Ouverte','🔓'],['fermee','Fermée','🔒'],['epreuve','Épreuve','🧪'],['manip','Manipulation','🔁'],['iso','Isolation / calorifuge','🧤'],['fuite','Fuite / défaut','⚠'],['reception','Réception','✅'],['autre','Autre','📝'],['suivi','Suivi (point ajouté)','📍']];
const ctxOf=k=>CTX.find(c=>c[0]===k)||[k,k||'—','📝'];
const NAT={vanne:['Vanne','🔧','#1c3d6b'],purge:['Purge','▲','#0b7a75'],vidange:['Vidange','▼','#2a5fb4'],sst:['Sous-station','🏭','#6b4bd6'],racc:['Raccordement','🔗','#a23b72'],bypass:['By-pass','↩','#3d3d3a']};
const RACC={pec:'Raccordement PEC',insertion:'Insertion de tés',attente:'Sur attente existante',chaufferie:'Raccordement chaufferie',attente_chaufferie:'Attente en chaufferie'};
const ETAT_NAT=['vanne','purge','vidange']; // natures qui ont un état ouvert / fermé
const PT_KPM=3; // zoom (px écran par mètre) à partir duquel les pastilles sont dessinées (les pièces deviennent lisibles)
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:1});
const dhm=x=>{if(!x)return '';const d=new Date(x);if(isNaN(d))return '';return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;};
const dFR=x=>x?new Date(x).toLocaleDateString('fr-FR'):'';
const slug=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^\w.-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,60)||'x';
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const CSS=`.pt-row{display:flex;align-items:center;gap:10px;padding:9px 6px;border-bottom:1px solid var(--line);min-height:54px;cursor:pointer}.pt-row:last-child{border-bottom:0}.pt-row .pt-ic{font-size:21px;width:30px;text-align:center;flex:none}.pt-row .pt-main{flex:1;min-width:0}.pt-row .pt-main b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pt-row .hint{margin-top:2px}.pt-row .btn{flex:none;min-height:40px}.pt-min{display:none}
.pt-st{display:inline-flex;align-items:center;gap:4px;border-radius:999px;padding:3px 9px;font-size:12.5px;font-weight:600;background:#eeede8;color:var(--ink2);white-space:nowrap}.pt-st.ouv{background:#e6f6e6;color:#1d5c1d}.pt-st.fer{background:#fdecec;color:#8a1f1f}.pt-st.alert{background:#fff3d6;color:#7a5200}
.pt-etat{display:flex;gap:8px;margin-top:4px}.pt-big{min-height:54px;font-size:16px;flex:1;padding:10px}.pt-ctx{flex-wrap:wrap;margin-top:2px}.pt-ctx .chip{min-height:40px;padding:8px 12px;font-size:14px;cursor:pointer}
.pt-con{border:1px solid var(--line);border-radius:12px;padding:9px 10px;margin-top:8px;background:var(--surface)}.pt-con .thumbs .thumb{width:96px;height:72px;cursor:pointer}.pt-con .hd{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.pt-con .hd .hint{flex:1;margin:0;min-width:120px}.pt-con .btn.sm{min-height:34px}
.pt-kpi{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.pt-kpi div{flex:1;min-width:100px;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:8px 10px;font-size:12.5px;color:var(--ink2)}.pt-kpi b{font-size:21px;display:block;color:var(--ink)}.pt-kpi div.ko b{color:#d03b3b}
.pt-filters{display:flex;gap:6px;flex-wrap:wrap;margin:6px 0 8px}.pt-filters .chip{min-height:40px;padding:8px 12px;font-size:13.5px;cursor:pointer}.pt-line{margin:12px 0 2px;font-size:14px}.pt-photo{min-height:52px;font-size:16px}.pt-photo input{display:none}
.pt-el{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:8px;padding:8px 10px;border:1.5px solid #1c3d6b;border-radius:12px;background:#f3f6fb}.pt-el .btn{min-height:40px}
.pt-step{display:flex;gap:10px;align-items:flex-start;padding:9px 8px;border:1px solid var(--line);border-radius:12px;margin-top:6px;background:var(--surface)}.pt-step.next{border-color:#1c3d6b;box-shadow:0 0 0 2px rgba(28,61,107,.15)}.pt-step.done{opacity:.75}.pt-step .num{flex:none;width:30px;height:30px;border-radius:50%;background:#eeede8;display:flex;align-items:center;justify-content:center;font-weight:700}.pt-step.next .num{background:#1c3d6b;color:#fff}.pt-step.done .num{background:#e6f6e6;color:#1d5c1d}.pt-step .main{flex:1;min-width:0}.pt-step .main b{display:block}.pt-step .act{display:flex;flex-direction:row;gap:4px;flex:none;align-items:center}.pt-step .act .btn.sm{min-height:34px;padding:4px 8px}.pt-step .act .ptq-fait{min-height:48px;font-size:15px;padding:8px 14px} /* .pt-done existe déjà (carte pointage) : classe à part, spécificité au-dessus de .btn.primary (≤ 600 px : 40 px) */
.pt-warn{color:#7a5200;background:#fff3d6;border-radius:8px;padding:4px 8px;font-size:12.5px;margin-top:4px}.pt-prog{height:8px;border-radius:4px;background:#e1e0d9;overflow:hidden;margin:6px 0 2px}.pt-prog div{height:100%;background:#0ca30c}.pt-tools{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0 10px}.pt-tools .btn{min-height:40px}.pt-pick{display:flex;flex-wrap:wrap;gap:6px;margin:4px 0}.pt-pick .chip{min-height:40px;padding:8px 12px;font-size:14px;cursor:pointer}.pt-modop{margin-bottom:10px}
@media (max-width:480px){.pt-row .btn{padding:6px 8px;font-size:12.5px}.pt-full{display:none}.pt-min{display:inline}.sheet .head .badge.pt-nat{display:none}.pt-step{flex-wrap:wrap}.pt-step .act{flex-direction:row;flex-wrap:wrap;width:100%;justify-content:flex-end;gap:6px}.pt-step .act .ptq-fait{flex:1;min-height:52px}}`;
function css(){if(typeof document==='undefined'||document.getElementById('css-lot-pa'))return;const s=document.createElement('style');s.id='css-lot-pa';s.textContent=CSS;document.head.appendChild(s);}
/* ── le point : nature, clé, étiquette ── */
export function natureOf(e){if(!e||e.link)return null;if(e.kind==='valve')return 'vanne';if(e.kind==='tee'&&e.vert)return (e.pvKind||(e.vert==='down'?'vidange':'purge'))==='vidange'?'vidange':'purge';if(e.kind==='endpoint')return e.sub==='sousstation'?'sst':'racc';if(e.kind==='bypass')return 'bypass';return null;}
const pkOf=e=>+(((+e.m0||0)+(+e.m1||0))/2).toFixed(1);
export const keyOf=(lineId,nature,pk)=>lineId+'|'+nature+'@'+(+pk).toFixed(1);
const cap=s=>{s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);};
const natLabel=p=>NAT[p.nature]?(p.nature==='racc'&&p.e&&RACC[p.e.sub]?RACC[p.e.sub]:NAT[p.nature][0]):cap((p.e&&p.e.kindLabel)||(A&&A.KLABEL&&A.KLABEL[p.nature])||p.nature);
const natIcon=p=>NAT[p.nature]?NAT[p.nature][1]:'📍';
const natCol=p=>NAT[p.nature]?NAT[p.nature][2]:'#52514e';
const labelShort=p=>natLabel(p)+(p.dn?' DN'+p.dn:'')+' · PK '+fmt(p.pk);
const labelOf=p=>labelShort(p)+' · '+(p.lineName||p.line);
// éléments « axe partagé » d'une ligne : session (l.els avec PK), brute du traceur (cond.A.els), brute DXF (els sans PK → cumul des longueurs)
function elsOfLine(l){let els=Array.isArray(l.els)&&l.els.length?l.els:((l.cond&&(l.cond.A||l.cond.R)&&(l.cond.A||l.cond.R).els)||[]);if(els.length&&els[0]&&els[0].m0===undefined){let m=0;els=els.map(e=>{const o=Object.assign({},e,{m0:m,m1:m+(+e.len||0)});m+=(+e.len||0);return o;});}return els;}
function basePoints(lines){const out=[];(lines||[]).forEach(l=>{if(!l||l.ghost||!l.id)return;elsOfLine(l).forEach((e,i)=>{if(!e||e.link)return;const nat=natureOf(e);const nature=nat||e.kind||'piece';const pk=pkOf(e);out.push({line:l.id,lineName:l.name||l.id,i,e,kind:e.kind,nature,auto:!!nat,pk,dn:+e.dn||+l.dn||null,dnb:e.dnb||null,key:keyOf(l.id,nature,pk),recs:[]});});});return out;}
const recsOfSite=siteId=>regAll('pteq').filter(r=>r&&r.site===siteId&&r.pt&&r.ctx!=='modop').sort((a,b)=>String(b.at||'').localeCompare(String(a.at||'')));
function finish(p){p.recs.sort((a,b)=>String(b.at||'').localeCompare(String(a.at||'')));p.etatRec=p.recs.find(r=>r.etat==='ouverte'||r.etat==='fermee')||null;p.nPhotos=p.recs.reduce((s,r)=>s+((r.photos||[]).length),0);p.last=p.recs[0]||null;p.alert=!!(p.last&&p.last.ctx==='fuite');p.glyph=p.alert?'⚠':p.etatRec?(p.etatRec.etat==='ouverte'?'🔓':'🔒'):p.nPhotos?'📷':'○';return p;}
/* tous les points d'un chantier : pièces du tracé (auto ou suivies) + constats orphelins (« pièce absente du tracé actuel ») */
export function pointsOf(siteId,lines){const base=basePoints(lines);const byKey={};base.forEach(p=>{byKey[p.key]=p;});const groups={};recsOfSite(siteId).forEach(r=>{(groups[r.pt]=groups[r.pt]||[]).push(r);});
  const out=[];Object.keys(groups).forEach(k=>{const rs=groups[k];let p=byKey[k];
    if(!p){const r0=rs[0];let pk=+r0.pk;if(!isFinite(pk)){const m=/@(-?[\d.]+)$/.exec(k);pk=m?+m[1]:NaN;}const cands=base.filter(q=>q.line===r0.ligne&&q.nature===r0.nature&&isFinite(pk)&&Math.abs(q.pk-pk)<=1.0).sort((a,b)=>Math.abs(a.pk-pk)-Math.abs(b.pk-pk));p=cands[0]||null;} /* PK qui a bougé d'un rien (tracé refait) : même pièce */
    if(p)p.recs.push(...rs);else{const r0=rs[0];out.push(finish({line:r0.ligne||'',lineName:r0.ligneNom||r0.ligne||'',i:-1,e:null,kind:'',nature:r0.nature||'piece',auto:false,pk:+r0.pk||0,dn:r0.dn||null,key:k,recs:rs.slice(),absent:true,label:r0.label||''}));}});
  base.forEach(p=>{if(p.auto||p.recs.length)out.push(finish(p));});return out;}
const sessionPoints=()=>A.state.siteId?pointsOf(A.state.siteId,Object.values(A.state.lines||{})):[];
const pointByKey=key=>sessionPoints().find(p=>p.key===key)||null;
/* ── droits ── */
const myKey=()=>A.userKey();
const isMgr=()=>{try{if(A.isAdmin())return true;if(A.can('weld.admin'))return true;const r=(A.me()||{}).role;return r==='chef'||r==='bureau';}catch(e){return false;}};
const canWrite=()=>{try{return A.can('conv.post')||isMgr();}catch(e){return false;}};
const canDel=r=>isMgr()||(r&&r.byKey&&r.byKey===myKey());
/* ── enregistrement : registre + file des photos hors connexion ── */
const PQ=new Set();let PUMPING=false,QLOADED=null;
const saveQ=()=>{try{A.kv.set('trace:pteqUp',[...PQ]);}catch(e){}};
function loadQ(){if(!QLOADED)QLOADED=(async()=>{try{const q=await A.kv.get('trace:pteqUp');if(Array.isArray(q))q.forEach(id=>PQ.add(id));}catch(e){}})();return QLOADED;}
const hasData=ph=>(ph||[]).some(p=>p&&typeof p.u==='string'&&p.u.startsWith('data:'));
const folderOf=r=>'pt_'+slug(String(r.pt||'pt').replace(/[|@]/g,'_'));
function store(id,d){const local=A.isSandbox(d.site)||hasData(d.photos);regSet('pteq',id,d,local?{local:true}:undefined);if(local&&!A.isSandbox(d.site)){PQ.add(id);saveQ();pump();}}
function patch(id,p){const r=regGet('pteq',id);if(!r)return;const local=A.isSandbox(r.site)||PQ.has(id)||hasData(p.photos)||hasData(r.photos);regSet('pteq',id,p,local?{local:true}:undefined);if(local&&!A.isSandbox(r.site)){PQ.add(id);saveQ();pump();}}
export async function pump(){await loadQ();if(PUMPING||!PQ.size||!A.state.cloudUser)return;PUMPING=true;let sent=0;
  try{for(const id of [...PQ]){const r=regGet('pteq',id);if(!r||A.isSandbox(r.site)){PQ.delete(id);continue;}
      if(r.deleted){PQ.delete(id);continue;} /* supprimé avant d'être parti : rien à envoyer */
      let ok=true;const photos=[];for(const p of (r.photos||[])){if(p&&typeof p.u==='string'&&p.u.startsWith('data:')){let u=null;try{u=await A.uploadPhoto(r.site,folderOf(r),p.u);}catch(e){console.warn('photo point',e);}if(!u){ok=false;photos.push(p);}else photos.push(Object.assign({},p,{u}));}else photos.push(p);}
      if(!ok){regSet('pteq',id,{photos},{local:true,quiet:true});break;} /* toujours pas de réseau : on garde, on réessaiera */
      const full=Object.assign({},regGet('pteq',id),{photos});delete full.id;PQ.delete(id);regSet('pteq',id,full);sent++;}}
  finally{PUMPING=false;saveQ();if(sent)A.toast(sent>1?sent+' constats envoyés (photos en ligne)':'Constat envoyé (photos en ligne)');}}
export const pendingPhotos=()=>PQ.size;
function newRec(P,o){const site=A.state.siteId;const id=site+'|'+P.key+'|'+uid();const key=myKey();const d={site,pt:P.key,nature:P.nature,ligne:P.line,ligneNom:P.lineName,pk:P.pk,dn:P.dn||null,label:labelOf(P),ctx:o.ctx,etat:o.etat||null,photos:o.photos||[],note:o.note||'',step:o.step||null,by:key,byKey:key,byName:A.userName(),at:new Date().toISOString()};Object.keys(d).forEach(k=>{if(d[k]===null)delete d[k];}); /* une valeur null dans un patch du registre EFFACE la clé : on n'envoie que ce qui existe */store(id,d);return id;}
function addPhotos(id,photos){const r=regGet('pteq',id);if(!r)return;patch(id,{photos:[...(r.photos||[]),...photos]});}
function delRec(id){const r=regGet('pteq',id);if(!r)return false;if(!canDel(r)){A.toast('Ce constat est à '+(r.byName||'quelqu\'un d\'autre')+' : seul son auteur ou l\'encadrement peut le retirer');return false;}
  const p={deleted:true,deletedAt:new Date().toISOString(),deletedBy:A.userName(),byKey:r.byKey||myKey()};if(PQ.has(id)){PQ.delete(id);saveQ();} /* photos jamais parties : plus rien à envoyer ; le retrait part quand même (la ligne a pu être envoyée avant les photos) */regSet('pteq',id,p,A.isSandbox(r.site)?{local:true}:undefined);return true;}
/* ── photos : compression ≤ 1 280 px + dimensions ── */
async function readPhotos(files){const out=[];for(const f of files){try{const u=await A.compressPhoto(f,1280,.78);if(!u)continue;const dim=await new Promise(res=>{const im=new Image();im.onload=()=>res({w:im.naturalWidth,h:im.naturalHeight});im.onerror=()=>res({w:null,h:null});im.src=u;});out.push({u,w:dim.w,h:dim.h});}catch(e){console.warn('photo',e);}}return out;}
/* ── fiche du point ── */
const PS={form:false,pending:[],ctx:null,note:'',ask:null,busy:false};const resetPS=()=>{PS.form=false;PS.pending=[];PS.ctx=null;PS.note='';PS.ask=null;PS.busy=false;};
const curPoint=()=>{const s=A.state.sel;if(!s||s.kind!=='pt')return null;return pointByKey(s.pt);};
function openPoint(key,o){o=o||{};const P=pointByKey(key);if(!P){A.toast('Point introuvable');return false;}const S=A.state;S.sel={kind:'pt',pt:key,line:P.line,cond:'A',i:P.i};S.sheetMode='view';if(!o.keep)resetPS();
  if(P.e&&S.tab==='plan'){try{const q=posOf(P);if(q)A.ensureVisible(q.x,q.y);}catch(e){}}A.renderSheet();A.openUI();A.renderPlan();return true;}
export function ptseqOpen(key){return openPoint(key);}
/* tap sur une pièce du plan : un point (pièce auto ou suivie) → sa fiche ; la conduite retour → le point de l'aller le plus proche (même nature, ≤ 5 m) */
export function ptseqTapEl(lineId,c,i){try{const l=A.state.lines[lineId];const e=l&&l.cond&&l.cond[c]&&l.cond[c].els[i];if(!e||e.link)return false;const pts=sessionPoints().filter(p=>p.line===lineId&&!p.absent);
    let P=null;if(c==='A'||l.single)P=pts.find(p=>p.i===i)||null;else{const nat=natureOf(e)||e.kind;const pk=pkOf(e);P=pts.filter(p=>p.nature===nat&&Math.abs(p.pk-pk)<=5).sort((a,b)=>Math.abs(a.pk-pk)-Math.abs(b.pk-pk))[0]||null;}
    if(!P)return false;return openPoint(P.key);}catch(e){console.warn('point',e);return false;}}
const etatTxt=r=>r?(r.etat==='ouverte'?'🔓 Ouverte':'🔒 Fermée'):'';
function conHTML(r,P){const c=ctxOf(r.ctx);const ph=(r.photos||[]).filter(p=>p&&p.u);const wait=PQ.has(r.id)||hasData(ph);
  return `<div class="pt-con" data-ptid="${esc(r.id)}"><div class="hd"><span class="pt-st ${r.etat==='ouverte'?'ouv':r.etat==='fermee'?'fer':r.ctx==='fuite'?'alert':''}">${c[2]} ${esc(c[1])}</span><span class="hint">${esc(dhm(r.at))} · ${esc(r.byName||r.by||'')}</span>${canDel(r)?`<button class="btn sm" data-pact="del" data-id="${esc(r.id)}" title="retirer ce constat">🗑</button>`:''}</div>
   ${ph.length?`<div class="thumbs">${ph.map((p,k)=>`<div class="thumb" data-pact="view" data-id="${esc(r.id)}" data-k="${k}"><img src="${esc(p.u)}" loading="lazy" alt=""></div>`).join('')}</div>`:(r.ctx==='suivi'?'':'<div class="hint">sans photo</div>')}${canWrite()&&canDel(r)&&!P.absent?`<label class="btn sm" style="margin-top:6px;min-height:34px">📷 ajouter<input type="file" accept="image/*" capture="environment" multiple data-ptph="${esc(r.id)}" style="display:none"></label>`:''}
   ${r.note?`<div style="font-size:13.5px;margin-top:5px">${esc(r.note)}</div>`:''}${wait?'<div class="hint">⏳ photos gardées sur cet appareil, envoyées dès que le réseau revient</div>':''}</div>`;}
function formHTML(P){return `<div class="card" style="margin-top:8px;border-color:#1c3d6b"><b>Nouveau constat</b>${PS.pending.length?`<div class="thumbs">${PS.pending.map((p,k)=>`<div class="thumb" data-pact="unpend" data-k="${k}" title="retirer"><img src="${esc(p.u)}" alt=""></div>`).join('')}</div>`:'<div class="hint">Constat sans photo : une note suffit.</div>'}
   <label class="btn sm" style="margin-top:6px;min-height:40px">📷 ＋ photos<input type="file" accept="image/*" capture="environment" multiple data-ptph="new" style="display:none"></label>
   <label class="f">Contexte</label><div class="chips pt-ctx">${CTX.filter(c=>c[0]!=='suivi'&&(ETAT_NAT.includes(P.nature)||(c[0]!=='ouverte'&&c[0]!=='fermee'))).map(c=>`<button class="chip ${PS.ctx===c[0]?'on':''}" data-pact="ctx" data-v="${c[0]}">${c[2]} ${esc(c[1])}</button>`).join('')}</div>
   <label class="f">Note (facultatif)</label><textarea class="f" data-ptnote placeholder="ex. vanne dure à manœuvrer">${esc(PS.note)}</textarea>
   <div class="actions"><button class="btn primary block" data-pact="save" ${PS.busy?'disabled':''}>${PS.busy?'⏳ Enregistrement…':'Enregistrer le constat'}</button><button class="btn block" data-pact="cancel">Annuler</button></div></div>`;}
export function ptseqSheetHTML(){const P=curPoint();if(!P)return `<div class="grab"></div><div class="head"><b>📍 Point</b><button class="iconbtn x" data-act="close">✕</button></div><div class="warnbox">Point introuvable sur ce chantier.</div>`;
  const nat=natLabel(P);const hasEtat=ETAT_NAT.includes(P.nature)||!!P.etatRec;const er=P.etatRec;const w=canWrite()&&!P.absent;const missing=regMissing('pteq');
  let h=`<div class="grab"></div><div class="head"><b>📍 ${esc(nat)}${P.dn?' DN'+esc(P.dn):''}${P.e&&P.e.id?' · '+esc(P.e.id):''}</b><span class="badge pt-nat" style="background:${natCol(P)}">${natIcon(P)} ${esc(nat)}</span><button class="iconbtn x" data-act="close">✕</button></div>
   <div class="kv" style="margin-top:6px"><span>${esc(P.lineName||P.line)}</span><span>PK <b>${fmt(P.pk)}</b> m</span>${P.dn?`<span>DN ${esc(P.dn)}${P.dnb?' (branche DN'+esc(P.dnb)+')':''}</span>`:''}<span class="pt-st ${P.alert?'alert':er?(er.etat==='ouverte'?'ouv':'fer'):''}">${P.glyph} ${P.alert?'à voir':er?(er.etat==='ouverte'?'ouverte':'fermée'):P.nPhotos?P.nPhotos+' photo'+(P.nPhotos>1?'s':''):'rien'}</span></div>
   ${P.absent?'<div class="warnbox">Pièce absente du tracé actuel (tracé refait) : les constats restent consultables, plus de nouveau constat ici.</div>':''}${missing?'<div class="warnbox">Serveur : le registre des points n\'est pas encore installé (sql/retours_20-10.sql) — les constats restent sur cet appareil et partiront ensuite.</div>':''}`;
  if(hasEtat){h+=`<h3>État</h3>${w?`<div class="pt-etat"><button class="btn pt-big ${er&&er.etat==='ouverte'?'primary':''}" data-pact="etat" data-v="ouverte">🔓 Ouverte</button><button class="btn pt-big ${er&&er.etat==='fermee'?'primary':''}" data-pact="etat" data-v="fermee">🔒 Fermée</button></div>`:`<div>${er?etatTxt(er):'—'}</div>`}
    <div class="hint" data-ptsince>${er?`${etatTxt(er)} depuis le ${esc(dhm(er.at))} par ${esc(er.byName||er.by||'')}`:'état non renseigné'}</div>
    ${PS.ask&&w?`<div class="warnbox" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><span style="flex:1;min-width:140px">📷 Prends la ${esc(nat.toLowerCase())} en photo (${esc(PS.ask.label)})</span><label class="btn" style="min-height:44px">📷 Photo<input type="file" accept="image/*" capture="environment" multiple data-ptph="${esc(PS.ask.id)}" style="display:none"></label><button class="btn sm" data-pact="noask" style="min-height:34px">plus tard</button></div>`:''}`;}
  h+=`<h3>Constats (${P.recs.length})</h3>${w?`<label class="btn primary block pt-photo">📷 Ajouter des photos<input type="file" accept="image/*" capture="environment" multiple data-ptph="new"></label>${PS.form?'':'<button class="btn sm" data-pact="form" style="margin-top:6px;min-height:34px">✎ Constat sans photo</button>'}`:(P.absent?'':'<div class="hint">Lecture seule (droit « conversation » nécessaire pour ajouter un constat).</div>')}
   ${PS.form&&w?formHTML(P):''}${P.recs.map(r=>conHTML(r,P)).join('')||(w?'<div class="hint" style="margin-top:6px">Aucun constat pour l\'instant : une photo de la pièce posée, de la pénétration, de l\'épreuve…</div>':'')}
   <div class="actions">${P.e&&P.i>=0?`<button class="btn block" data-pact="piece">🔧 Pièce : orientation des fils, état DH, remarque</button>`:''}${!P.auto&&!P.absent&&isMgr()?`<button class="btn block" data-pact="unfollow" data-pt="${esc(P.key)}">Ne plus suivre ce point</button>`:''}<button class="btn block" data-pact="list">📍 Tous les points du chantier</button><button class="btn block" data-act="close">Fermer</button></div>`;
  return h;}
function rerenderSheet(){const sh=document.getElementById('sheet');if(!sh||!A.state.sel||A.state.sel.kind!=='pt')return;const y=sh.scrollTop;const ta=sh.querySelector('[data-ptnote]');if(ta&&PS.form)PS.note=ta.value; /* la note tapée survit à un redessin (données reçues) — seulement tant que le formulaire est ouvert */A.renderSheet();sh.scrollTop=y;}
async function onPhotos(target,files){const P=curPoint();if(!P||!files.length)return;A.toast(files.length>1?'Lecture de '+files.length+' photos…':'Lecture de la photo…');const ph=await readPhotos(files);if(!ph.length){A.toast('Photo illisible');return;}
  if(target==='new'){PS.pending.push(...ph);PS.form=true;rerenderSheet();return;}
  if(PS.ask&&PS.ask.id===target)PS.ask=null;addPhotos(target,ph);A.toast(ph.length>1?ph.length+' photos ajoutées':'Photo ajoutée');}
function saveForm(){const P=curPoint();if(!P||PS.busy)return;if(!PS.ctx){A.toast('Choisis le contexte (pénétration, épreuve, ouverte…)');return;}const ta=document.querySelector('#sheet [data-ptnote]');const note=(ta?ta.value:PS.note||'').trim();if(!PS.pending.length&&!note){A.toast('Ajoute une photo ou une note');return;}
  const ctx=PS.ctx;const etat=ctx==='ouverte'?'ouverte':ctx==='fermee'?'fermee':null;const photos=PS.pending;const n=photos.length;resetPS(); /* vidé AVANT l'écriture : elle redessine la fiche (sinon le formulaire restait affiché avec sa note) */newRec(P,{ctx,etat,photos,note});A.toast('Constat « '+ctxOf(ctx)[1]+' » enregistré'+(n?' · '+n+' photo'+(n>1?'s':''):''));}
function setEtat(v){const P=curPoint();if(!P)return;if(P.etatRec&&P.etatRec.etat===v){A.toast('Déjà '+(v==='ouverte'?'ouverte':'fermée')+' depuis le '+dhm(P.etatRec.at));return;}const id=newRec(P,{ctx:v,etat:v,photos:[]});PS.ask={id,label:v==='ouverte'?'ouverte':'fermée'};rerenderSheet();A.toast((v==='ouverte'?'🔓 Ouverte':'🔒 Fermée')+' — prends-la en photo');}
function viewPhoto(id,k){const r=regGet('pteq',id);const p=r&&(r.photos||[])[k];if(!p)return;const c=ctxOf(r.ctx);A.openModal(`<div style="text-align:center"><img src="${esc(p.u)}" style="max-width:100%;max-height:70vh;border-radius:10px" alt=""><div class="hint" style="margin-top:6px">${esc(r.label||'')} · ${c[2]} ${esc(c[1])} · ${esc(dhm(r.at))} · ${esc(r.byName||'')}${r.note?' — '+esc(r.note):''}</div></div><div class="actions"><button class="btn block" data-close>Fermer</button></div>`);}
function follow(lineId,c,i){const l=A.state.lines[lineId];const e=l&&l.cond&&l.cond[c]&&l.cond[c].els[i];if(!e)return;if(!isMgr()){A.toast('Suivre une pièce : réservé à l\'encadrement');return;}const base=basePoints([l]).find(p=>p.i===i);if(!base)return;
  const P=pointByKey(base.key)||Object.assign(base,{recs:[]});newRec(P,{ctx:'suivi',photos:[],note:'Point suivi ajouté par '+A.userName()});A.toast('📍 Point suivi : '+labelShort(P));openPoint(base.key);}
function unfollow(key){const P=pointByKey(key);if(!P||!isMgr())return;const others=P.recs.filter(r=>r.ctx!=='suivi');if(others.length){A.toast('Ce point a des constats : retire-les d\'abord');return;}P.recs.filter(r=>r.ctx==='suivi').forEach(r=>delRec(r.id));A.toast('Point retiré du suivi');A.closeSheet();}
/* bloc dans la fiche PIÈCE (elView) : point → ouvrir sa fiche ; autre pièce → « Suivre ce point » (encadrement) */
export function ptseqElBlock(l,c,i){try{const e=l&&l.cond&&l.cond[c]&&l.cond[c].els[i];if(!e||e.link)return '';const pts=sessionPoints().filter(p=>p.line===l.id&&!p.absent);let P=null;
    if(c==='A'||l.single)P=pts.find(p=>p.i===i)||null;else{const nat=natureOf(e)||e.kind;const pk=pkOf(e);P=pts.filter(p=>p.nature===nat&&Math.abs(p.pk-pk)<=5).sort((a,b)=>Math.abs(a.pk-pk)-Math.abs(b.pk-pk))[0]||null;}
    if(P)return `<div class="pt-el"><span style="flex:1;min-width:140px"><b>📍 Point de contrôle</b> — ${P.glyph} ${P.etatRec?esc(etatTxt(P.etatRec))+' depuis le '+esc(dhm(P.etatRec.at)):P.nPhotos?P.nPhotos+' photo'+(P.nPhotos>1?'s':''):'aucun constat'}</span><button class="btn sm" data-pact="openpt" data-pt="${esc(P.key)}">Fiche du point</button>${!P.auto&&isMgr()?`<button class="btn sm" data-pact="unfollow" data-pt="${esc(P.key)}">Ne plus suivre</button>`:''}</div>`;
    if(isMgr())return `<div class="pt-el" style="border-style:dashed;background:transparent"><span style="flex:1;min-width:140px" class="hint">Cette pièce n'est pas un point de contrôle.</span><button class="btn sm" data-pact="follow" data-line="${esc(l.id)}" data-cond="${esc(c)}" data-i="${i}">📍 Suivre ce point (photos, état)</button></div>`;return '';}catch(e){console.warn('point',e);return '';}}
/* ── pastilles sur le plan (groupe #ptG dans #markers) ── */
function posOf(P){if(!P.e)return null;const mid=A.elMid(P.e);let tx=mid.tx,ty=mid.ty;if(Math.hypot(tx,ty)<1e-6){const l=A.state.lines[P.line];const els=l&&l.els;const n=els&&(els[P.i-1]||els[P.i+1]);if(n){const m2=A.elMid(n);tx=m2.tx;ty=m2.ty;}if(Math.hypot(tx,ty)<1e-6){tx=1;ty=0;}}return {x:mid.x,y:mid.y,tx,ty};}
export function ptseqOverlay(){const g=document.getElementById('ptG');if(!g||!A)return;const S=A.state;const NET=A.net();if(S.screen!=='site'||!NET||NET.id==='__vide'||S.show.points===false){g.innerHTML='';return;}
  const sh=A.sheet();if(!sh){g.innerHTML='';return;}const k=S.view.k,ppm=sh.ppm||1,kpm=k*ppm;if(kpm<PT_KPM){g.innerHTML='';return;}
  const cv=document.getElementById('canvas');const v=S.view;const vx0=(-v.tx)/k-60/k,vy0=(-v.ty)/k-60/k,vx1=((cv?cv.clientWidth:400)-v.tx)/k+60/k,vy1=((cv?cv.clientHeight:500)-v.ty)/k+60/k;
  const sel=S.sel&&S.sel.kind==='pt'?S.sel.pt:null;let s='';
  sessionPoints().forEach(P=>{if(P.absent||!P.e||!sh.lines.includes(P.line))return;const q=posOf(P);if(!q||!isFinite(q.x))return;if(q.x<vx0||q.x>vx1||q.y<vy0||q.y>vy1)return;
    const wpx=Math.max(2.2,A.casingOf(P.e)*ppm*k*(kpm>=12?1.15:1.7));const off=Math.max(36,wpx*.62+13+8.5+16)/k; /* au-delà des pastilles de soudure (côté aller, à l'extérieur), jamais sur les fils */
    const px=q.x+q.ty*off,py=q.y-q.tx*off;const er=P.etatRec;const stroke=P.alert?'#b8560f':er?(er.etat==='ouverte'?'#0ca30c':'#d03b3b'):P.nPhotos?'#2a78d6':'#898781';const fill=P.alert?'#fff3d6':'#fff';const on=sel===P.key;
    s+=`<g data-pt="${esc(P.key)}" style="cursor:pointer"><line x1="${q.x.toFixed(2)}" y1="${q.y.toFixed(2)}" x2="${px.toFixed(2)}" y2="${py.toFixed(2)}" stroke="${stroke}" stroke-width="${1.4/k}" opacity=".85"/><g transform="translate(${px.toFixed(2)} ${py.toFixed(2)}) scale(${1/k})"><circle r="17" fill="transparent"/>${on?'<circle r="17" fill="none" stroke="#0b0b0b" stroke-width="2" stroke-dasharray="4 3"/>':''}<circle r="12" fill="${fill}" stroke="${stroke}" stroke-width="${on?3:2.2}"/><text y="4.5" font-size="12" text-anchor="middle" font-family="system-ui,sans-serif" style="pointer-events:none">${P.glyph}</text>${!P.auto?'<circle cx="9" cy="-9" r="4" fill="#1c3d6b" stroke="#fff" stroke-width="1.2"/>':''}</g></g>`;});
  g.innerHTML=s;}
/* ── onglet « 📍 Points » ── */
const FILTERS=[['all','Tous'],['nophoto','Sans photo'],['vanne','Vannes'],['pv','Purges / vidanges'],['sst','SST / raccordements'],['suivi','Autres suivis']];
const inFilter=(p,f)=>f==='all'?true:f==='nophoto'?!p.nPhotos:f==='vanne'?p.nature==='vanne':f==='pv'?(p.nature==='purge'||p.nature==='vidange'):f==='sst'?['sst','racc','bypass'].includes(p.nature):f==='suivi'?(!p.auto&&!p.absent):true;
export function ptseqCounts(pts){const live=pts.filter(p=>!p.absent);const nc=live.reduce((s,p)=>s+p.recs.length,0);return {n:live.length,nPhotos:live.reduce((s,p)=>s+p.nPhotos,0),nCons:nc,vSansEtat:live.filter(p=>p.nature==='vanne'&&!p.etatRec).length,sansPhoto:live.filter(p=>!p.nPhotos).length,absents:pts.length-live.length};}
const rowHTML=(p,extra)=>`<div class="pt-row" data-pact="open" data-pt="${esc(p.key)}"><span class="pt-ic">${p.glyph}</span><div class="pt-main"><b>${natIcon(p)} ${esc(labelShort(p))}</b><div class="hint">${[p.etatRec?esc(etatTxt(p.etatRec))+' depuis le '+esc(dhm(p.etatRec.at))+' par '+esc(p.etatRec.byName||''):(ETAT_NAT.includes(p.nature)?'état non renseigné':''),p.nPhotos+' 📷',p.last?'dernier : '+esc(ctxOf(p.last.ctx)[1].toLowerCase())+' ('+esc(dhm(p.last.at))+')':'',extra||'',p.absent?'<b>pièce absente du tracé actuel</b>':''].filter(Boolean).join(' · ')}</div></div>${p.absent?'':`<button class="btn sm" data-pact="goto" data-pt="${esc(p.key)}" title="voir sur le plan"><span class="pt-full">Voir sur le plan</span><span class="pt-min">📐 Plan</span></button>`}</div>`;
export function ptseqRender(){const el=document.getElementById('points');if(!el)return;const NET=A.net();if(!NET||NET.id==='__vide'){el.innerHTML='<h2 class="vt">📍 Points de contrôle</h2><div class="card muted">Aucun chantier ouvert.</div>';return;}
  const S=A.state;const pts=sessionPoints();const C=ptseqCounts(pts);const f=S.ptFilter||'all';const shown=pts.filter(p=>inFilter(p,f));const nf=k=>pts.filter(p=>inFilter(p,k)).length;
  const groups={};shown.filter(p=>!p.absent).forEach(p=>{(groups[p.line]=groups[p.line]||{name:p.lineName,pts:[]}).pts.push(p);});const orph=shown.filter(p=>p.absent);
  const row=p=>rowHTML(p,'');
  el.innerHTML=`<h2 class="vt">📍 Points de contrôle — ${esc(NET.name||'')}</h2>
   ${regMissing('pteq')?'<div class="warnbox" style="margin-bottom:8px">Serveur : le registre des points n\'est pas encore installé (sql/retours_20-10.sql) — les constats restent sur cet appareil et partiront ensuite.</div>':''}${PQ.size?`<div class="hint" style="margin-bottom:6px">⏳ ${PQ.size} constat${PQ.size>1?'s':''} avec photos en attente de réseau.</div>`:''}
   <div class="pt-kpi"><div><b>${C.n}</b>point${C.n>1?'s':''} · ${C.nPhotos} photo${C.nPhotos>1?'s':''}</div><div class="${C.vSansEtat?'ko':''}" data-ptk="vse"><b>${C.vSansEtat}</b>vanne${C.vSansEtat>1?'s':''} sans état</div><div class="${C.sansPhoto&&C.nCons?'ko':''}" data-ptk="sp"><b>${C.sansPhoto}</b>point${C.sansPhoto>1?'s':''} sans photo</div></div>
   <div class="hint" style="margin-bottom:4px">Vannes, purges, vidanges, sous-stations et raccordements du tracé. Touche un point → sa fiche (état ouvert / fermé daté, constats photo). Sur le plan : la pastille à côté de la pièce.</div>
   ${(()=>{let m2='';try{m2=A.modop&&A.modop()?A.modop().terrain():'';}catch(e){console.warn('modop',e);}let m='';try{const h=A.hydroOf?A.hydroOf():null;if(h&&h.modop&&Object.values(h.modop).some(a=>a&&a.length))m=modopHTML({canEdit:A.can('hydro'),where:'points'});}catch(e){console.warn('modop',e);}return (m2||m)?`<h3 class="pt-line">📋 Mode opératoire hydraulique</h3>${m2}${m?`<details><summary class="muted" style="cursor:pointer">Ancien mode opératoire (liste)</summary>${m}</details>`:''}`:'';})()}
   <div class="pt-filters">${FILTERS.filter(x=>x[0]!=='suivi'||nf('suivi')).map(([k,l])=>`<button class="chip ${f===k?'on':''}" data-pact="filter" data-v="${k}">${esc(l)} (${nf(k)})</button>`).join('')}</div>
   ${Object.keys(groups).length?Object.values(groups).map(g=>`<h3 class="pt-line">${esc(g.name)}</h3><div class="card" style="padding:2px 8px">${g.pts.sort((a,b)=>a.pk-b.pk).map(row).join('')}</div>`).join(''):'<div class="card muted">Aucun point'+(f!=='all'?' pour ce filtre':' sur ce tracé (pas de vanne, purge, vidange, sous-station ni raccordement)')+'.</div>'}
   ${orph.length?`<h3 class="pt-line">Pièces absentes du tracé actuel</h3><div class="card" style="padding:2px 8px">${orph.map(row).join('')}</div>`:''}`;}
function gotoPoint(key){const P=pointByKey(key);if(!P||!P.e){A.toast('Pièce absente du tracé actuel');return;}const S=A.state;const l=S.lines[P.line];if(l&&l.sheetId&&l.sheetId!==S.sheetId){S.sheetId=l.sheetId;}S.tab='plan';A.renderAll();const q=posOf(P);const sh=A.sheet();A.centerOn(q.x,q.y,Math.max(S.view.k,14/((sh&&sh.ppm)||1)));openPoint(key);}
/* ── onglet HYDRAULIQUE (20/10, suite PH) : vannes de sectionnement + mode opératoire par prestation ── */
const MOD_T={ouvrir:['Ouvrir','🔓'],fermer:['Fermer','🔒'],verifier:['Vérifier','👁'],op:['Opération','🌊'],purge:['Purger / vidanger','▲'],note:['Note','📝']};
const MOD_OPS=[['rincer','Rincer'],['pression','Mettre en pression'],['maintenir','Maintenir en pression'],['remplir','Remplir'],['vidanger','Vidanger'],['purger','Purger'],['controler','Contrôler']];
const opLabel=k=>(MOD_OPS.find(o=>o[0]===k)||[k,k||'opération'])[1];
const PRESTS=['rincage','epreuve','passivation','remplissage'];
const MS={prest:null,tron:null}; // vue du mode opératoire : prestation, tronçon (null = tout le réseau)
const isoDay=d=>{d=d||new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
const hyCtx=()=>{try{const h=A.hydroOf?A.hydroOf():null;const H=h&&A.hydroBuild?A.hydroBuild():null;return {h,H};}catch(e){console.warn('hydro',e);return {h:null,H:null};}};
const tcol=t=>{const C=A.TCOLS||['#1c3d6b'];return (t==null||t<0)?'#0b0b0b':C[t%C.length];};
const tronName=(H,t)=>t==null||t<0?'tout le réseau':'Tronçon '+(t+1)+(H&&H.troncons[t]?' — '+H.troncons[t].lines.map(id=>(A.state.lines[id]||{}).name||id).slice(0,2).join(' + '):'');
const byLinePk=(a,b)=>{const L=Object.keys(A.state.lines||{});return (L.indexOf(a.line)-L.indexOf(b.line))||(a.pk-b.pk);};
/* coches « Fait » = lignes du registre pteq portant step (la plus récente par étape) */
function marksOf(){const site=A.state.siteId;const by={};regAll('pteq').forEach(r=>{if(!r||r.site!==site||!r.step)return;const o=by[r.step];if(!o||String(r.at||'')>String(o.at||''))by[r.step]=r;});return by;}
const doneOf=(s,marks)=>{const m=marks[s.id];return m?{by:m.byName||m.by||'',byKey:m.byKey||'',at:m.at,id:m.id,constat:m.ctx!=='modop'}:null;};
export const ptseqMark=(prest,s)=>newMark(prest,s);export const ptseqMarks=()=>marksOf(); /* 23/10 : coches « Fait » du mode opératoire visuel (modop.js) */
function newMark(prest,s){const site=A.state.siteId;const id=site+'|modop|'+prest+'|'+s.id+'|'+uid();const key=myKey();const d={site,pt:'modop|'+prest+'|'+s.id,nature:'etape',ctx:'modop',step:s.id,prest,label:stepTitle(s,null),photos:[],by:key,byKey:key,byName:A.userName(),at:new Date().toISOString()};store(id,d);return id;}
const modOf=(h,prest,create)=>{if(!h)return [];if(!h.modop){if(!create)return [];h.modop={};}if(!h.modop[prest]){if(!create)return [];h.modop[prest]=[];}return h.modop[prest];};
/* coupe de sectorisation posée sur une vanne (H.cuts[].valve = id de la pièce) et les tronçons qu'elle sépare */
function cutInfo(P,H){if(!H||!P.e)return null;const c=H.cuts.find(c=>c.line===P.line&&c.valve&&c.valve===P.e.id);if(!c)return null;const ts=H.troncons.filter(t=>t.ends.some(en=>en.type==='cut'&&en.cut===c.idx)).map(t=>t.idx);return {c,ts};}
/* opération en cours sur un tronçon : pastille du calendrier datée d'aujourd'hui, ou fiche d'exécution renseignée mais non conclue */
function tronBusy(h,H,t){if(!h)return false;const today=isoDay();if((h.cal||[]).some(c=>(+c.t===t||+c.t===-1)&&c.d===today&&c.op!=='autre'))return true;
  return PRESTS.some(k=>{if(!h.prest||!h.prest[k]||!A.hydroExecOf)return false;const r=A.hydroExecOf(t,k);if(!r||!r.date)return false;const R=A.hxResult?A.hxResult(k,r):{code:''};return R.code==='enc';});}
function valveAlert(P,h,H){const ci=cutInfo(P,H);if(!ci||!P.etatRec||P.etatRec.etat!=='ouverte')return null;const busy=ci.ts.filter(t=>tronBusy(h,H,t));return busy.length?{ts:busy,ci}:null;}
/* carte de l'onglet Hydraulique : l'état de la vanne sur sa coupe + alerte « vanne de coupe OUVERTE » */
export function ptseqCutState(c){try{if(!A||!c||!c.valve)return null;const {h,H}=hyCtx();if(!H)return null;const P=sessionPoints().find(p=>p.nature==='vanne'&&!p.absent&&p.line===c.line&&p.e&&p.e.id===c.valve);if(!P)return null;const al=valveAlert(P,h,H);
    return {glyph:P.etatRec?(P.etatRec.etat==='ouverte'?'🔓':'🔒'):'',etat:P.etatRec?P.etatRec.etat:null,alert:!!al,txt:al?'⚠ vanne OUVERTE — en cours sur T'+al.ts.map(t=>t+1).join(', T'):''};}catch(e){console.warn('coupe',e);return null;}}
/* bloc de l'onglet Hydraulique (appelé par renderHydro) : vannes, purges / vidanges repliées, mode opératoire */
export function ptseqHydroHTML(H,h,canH){try{if(!H||!h)return '';const pts=sessionPoints().filter(p=>!p.absent);const V=pts.filter(p=>p.nature==='vanne').sort(byLinePk);const PV=pts.filter(p=>p.nature==='purge'||p.nature==='vidange').sort(byLinePk);const nSe=V.filter(p=>!p.etatRec).length;
    const extra=p=>{const ci=cutInfo(p,H);if(!ci)return '';return '✂ coupe de sectorisation : '+(ci.ts.length?ci.ts.map(t=>`<span style="color:${tcol(t)};font-weight:700">T${t+1}</span>`).join(' | '):'—');};
    const alerts=V.map(p=>({p,al:valveAlert(p,h,H)})).filter(x=>x.al);
    return `<h3 style="margin:10px 0 6px">2 bis · 🔧 Vannes de sectionnement <span class="muted" style="font-weight:400;font-size:12px">${V.length} vanne${V.length>1?'s':''} · ${nSe} sans état</span></h3>
   ${alerts.map(x=>`<div class="warnbox" style="margin:0 0 6px">⚠ <b>Vanne de coupe OUVERTE</b> — ${esc(labelShort(x.p))} (${esc(x.p.lineName)}) isole T${x.al.ts.map(t=>t+1).join(' / T')} où une opération est en cours (calendrier du jour ou fiche d'exécution ouverte). Rien ne bloque : vérifie sur place.</div>`).join('')}
   ${V.length?`<div class="card pt-vannes" style="padding:2px 8px">${V.map(p=>rowHTML(p,extra(p))).join('')}</div>`:'<div class="card muted pt-vannes">Aucune vanne sur le tracé.</div>'}
   ${PV.length?`<details class="pt-pv" style="margin:0 0 8px"><summary class="muted" style="cursor:pointer;font-size:13px">▲▼ Purges et vidanges (${PV.length})</summary><div class="card" style="padding:2px 8px;margin-top:6px">${PV.map(p=>rowHTML(p,'')).join('')}</div></details>`:''}
   <h3 style="margin:10px 0 6px">2 ter · 📋 Modes opératoires <span class="muted" style="font-weight:400;font-size:12px">(sur le plan : état de départ des vannes, puis remplir, purger, rincer, mettre en pression, attendre, casser la pression, vidanger… ; le terrain coche « Fait »)</span></h3>
   ${A.modop&&A.modop()?A.modop().list(canH):''}
   ${(()=>{const has=!!(h.modop&&Object.values(h.modop).some(a=>a&&a.length));const old=modopHTML({canEdit:canH,where:'hydro'});return old?`<details style="margin-top:6px"${has?' open':''}><summary class="muted" style="cursor:pointer;font-size:12.5px">Mode opératoire en liste, par prestation${has?'':' (ancienne façon)'}</summary>${old}</details>`:'';})()}`;}catch(e){console.warn('hydro points',e);return '';}} /* 23/10 : mode opératoire visuel (modop.js) d'abord ; la liste par prestation reste là (repliée si vide, ouverte si elle a des étapes) — rien de supprimé */
function stepTitle(s,H){const P=s.pt?pointByKey(s.pt):null;const t=MOD_T[s.type]||MOD_T.note;
  if(s.type==='ouvrir'||s.type==='fermer'||s.type==='verifier')return t[1]+' '+t[0]+' — '+(P?labelShort(P):(s.label||'vanne absente du tracé'));
  if(s.type==='purge')return (P?natIcon(P)+' ':'▲ ')+'Purger / vidanger — '+(P?labelShort(P):(s.label||'té absent du tracé'));
  if(s.type==='op')return '🌊 '+opLabel(s.op)+' — '+cap(tronName(H,s.tron));
  return '📝 '+(s.label||s.note||'note');}
function stepHTML(s,i,idx,n,prest,H,canEdit,isNext,marks){const P=s.pt?pointByKey(s.pt):null;const w=canWrite();const detail=[];const done=doneOf(s,marks);
  if(P)detail.push(esc(P.lineName)+(P.etatRec?' · état actuel : '+esc(etatTxt(P.etatRec))+' ('+esc(dhm(P.etatRec.at))+')':(ETAT_NAT.includes(P.nature)?' · état actuel : —':'')));if(s.pt&&!P)detail.push('<b>pièce absente du tracé actuel</b>');
  if(s.type==='op'){if(s.note)detail.push(esc(s.note));const r=s.tron!=null&&A.hydroExecOf?A.hydroExecOf(s.tron,prest):null;if(r){const R=A.hxResult(prest,r);detail.push(`📄 fiche d'exécution : <b style="color:${R.color}">${esc(R.label)}</b>`+(canEdit?` <button class="btn sm" data-pact="h-exec" data-t="${s.tron}" data-k="${esc(prest)}" style="min-height:30px;padding:2px 8px">ouvrir</button>`:''));}}
  else if(s.note&&s.type!=='note')detail.push(esc(s.note));
  if(s.tron!=null&&MS.tron==null)detail.push(`<span style="color:${tcol(s.tron)};font-weight:700">T${s.tron+1}</span>`);
  let warn='';if(!done&&P&&P.etatRec){if(s.type==='ouvrir'&&P.etatRec.etat==='ouverte')warn='déjà ouverte d\'après le dernier constat';if(s.type==='fermer'&&P.etatRec.etat==='fermee')warn='déjà fermée d\'après le dernier constat';}
  const mine=!!(done&&done.byKey&&done.byKey===myKey());
  return `<div class="pt-step ${done?'done':''} ${isNext?'next':''}" data-sid="${esc(s.id)}"><div class="num">${done?'✓':i+1}</div><div class="main"><b>${esc(stepTitle(s,H))}</b>${detail.length?`<div class="hint">${detail.join(' · ')}</div>`:''}${warn?`<div class="pt-warn">⚠ ${esc(warn)} — à vérifier sur place, rien ne bloque</div>`:''}${done?`<div class="hint">✓ fait par ${esc(done.by)} le ${esc(dhm(done.at))}${done.constat?' · constat enregistré sur le point':''}</div>`:''}</div>
   <div class="act">${!done&&w?`<button class="btn ${isNext?'primary':''} ptq-fait" data-pact="h-done" data-id="${esc(s.id)}">✓ Fait</button>`:''}${done&&(isMgr()||mine)?`<button class="btn sm" data-pact="h-undone" data-id="${esc(s.id)}" title="annuler « fait »">↶</button>`:''}${canEdit?`<button class="btn sm" data-pact="h-up" data-id="${esc(s.id)}" ${idx===0?'disabled':''}>↑</button><button class="btn sm" data-pact="h-down" data-id="${esc(s.id)}" ${idx>=n-1?'disabled':''}>↓</button><button class="btn sm" data-pact="h-del" data-id="${esc(s.id)}">✕</button>`:''}</div></div>`;}
function modopHTML(o){o=o||{};const {h,H}=hyCtx();if(!h||!H)return '';const canEdit=!!o.canEdit;const active=PRESTS.filter(k=>h.prest&&h.prest[k]);const all=h.modop||{};const withSteps=PRESTS.filter(k=>(all[k]||[]).length);
  const prests=[...new Set([...active,...withSteps])];if(!prests.length)return o.where==='points'?'':'<div class="hint">Coche d\'abord une prestation (1 · Prestations à préparer) : le mode opératoire se compose par prestation.</div>';
  if(!MS.prest||!prests.includes(MS.prest))MS.prest=withSteps[0]||prests[0];const prest=MS.prest;const steps=modOf(h,prest,false);
  if(o.where==='points'&&!withSteps.length&&!canEdit)return '';
  const marks=marksOf();const tron=MS.tron;const shown=tron==null?steps:steps.filter(s=>s.tron==null||s.tron===tron);const done=shown.filter(s=>marks[s.id]).length;const next=shown.find(s=>!marks[s.id]);const pct=shown.length?Math.round(100*done/shown.length):0;
  const prestChips=`<div class="chips pt-ctx" style="margin:2px 0 4px">${prests.map(k=>`<button class="chip ${prest===k?'on':''}" data-pact="h-prest" data-v="${k}">${esc(PREST_LABEL[k]||k)}${(all[k]||[]).length?' ('+(all[k]||[]).length+')':''}</button>`).join('')}</div>`;
  const tronChips=H.troncons.length>1?`<div class="chips pt-ctx" style="margin:0 0 6px"><button class="chip ${tron==null?'on':''}" data-pact="h-tron" data-v="">Tout le réseau</button>${H.troncons.map(t=>`<button class="chip ${tron===t.idx?'on':''}" data-pact="h-tron" data-v="${t.idx}" style="${tron===t.idx?'background:'+tcol(t.idx)+';border-color:'+tcol(t.idx):'border-color:'+tcol(t.idx)}">T${t.idx+1}</button>`).join('')}</div>`:'';
  const rows=shown.map((s,i)=>stepHTML(s,i,steps.indexOf(s),steps.length,prest,H,canEdit,s===next,marks)).join('');
  const bar=shown.length?`<div class="pt-prog"><div style="width:${pct}%"></div></div><div class="hint pt-progtxt">Fait : ${done} / ${shown.length}${next?' · suivante : <b>'+esc(stepTitle(next,H))+'</b>':' · ✓ mode opératoire terminé'}</div>`:`<div class="hint">Aucune étape pour cette prestation${canEdit?' : compose-les ci-dessous (＋ Ouvrir une vanne, ＋ Opération sur un tronçon…)':''}.</div>`;
  const addLab=t=>t==='op'?'Opération sur un tronçon':t==='note'?'Note libre':t==='purge'?'Purger / vidanger':MOD_T[t][0]+' une vanne';
  const tools=canEdit?`<div class="pt-tools">${Object.keys(MOD_T).map(t=>`<button class="btn sm" data-pact="h-add" data-v="${t}">＋ ${MOD_T[t][1]} ${esc(addLab(t))}</button>`).join('')}${tron!=null&&shown.some(s=>s.tron===tron)?`<button class="btn sm" data-pact="h-dup">⧉ Dupliquer pour un autre tronçon</button>`:''}${steps.length?`<button class="btn sm" data-pact="h-print">🖨 Imprimer le mode opératoire</button>`:''}</div>`:(steps.length?`<div class="pt-tools"><button class="btn sm" data-pact="h-print">🖨 Imprimer le mode opératoire</button></div>`:'');
  return `<div class="pt-modop" data-prest="${esc(prest)}">${prestChips}${tronChips}${bar}<div class="pt-steps">${rows}</div>${tools}</div>`;}
function hyRerender(){const S=A.state;if(S.tab==='hydro'&&A.renderHydro)A.renderHydro();else if(S.tab==='points')ptseqRender();}
function findStep(id){const {h}=hyCtx();if(!h||!h.modop)return null;for(const k of Object.keys(h.modop)){const i=(h.modop[k]||[]).findIndex(s=>s&&s.id===id);if(i>=0)return {prest:k,list:h.modop[k],i,s:h.modop[k][i]};}return null;}
function addStep(prest,st){const {h}=hyCtx();if(!h)return null;const list=modOf(h,prest,true);const s=Object.assign({id:'m'+uid(),type:'note',pt:null,tron:null,op:null,label:'',note:''},st);list.push(s);A.saveHydro();hyRerender();return s;}
/* « ✓ Fait » (terrain) : une étape vanne / té = un constat du point (état ouverte / fermée, photo proposée) ; une opération = marque dans le mode opératoire */
function doStep(id){const f=findStep(id);if(!f)return;if(marksOf()[id])return;if(!canWrite()){A.toast('Lecture seule');return;}const s=f.s;const n=f.i+1;const P=s.pt?pointByKey(s.pt):null;let rid=null;
  if(['ouvrir','fermer','verifier','purge'].includes(s.type)&&P){const etat=s.type==='ouvrir'?'ouverte':s.type==='fermer'?'fermee':null;rid=newRec(P,{ctx:etat||'manip',etat,photos:[],step:s.id,note:'Mode opératoire '+(PREST_LABEL[f.prest]||f.prest)+' — étape '+n+(s.type==='verifier'?' (vérification)':s.type==='purge'?' (purge / vidange)':'')});}
  else{if(s.pt&&!P)A.toast('Pièce absente du tracé actuel : étape marquée faite, sans constat');newMark(f.prest,s);} /* la coche est une ligne du registre (tout compte actif, hors connexion) : la partie « hydro » du chantier n'est pas réécrite par le terrain */
  hyRerender();
  if(P&&rid){resetPS();PS.ask={id:rid,label:s.type==='ouvrir'?'ouverte':s.type==='fermer'?'fermée':s.type==='purge'?'purge / vidange':'vérifiée'};openPoint(P.key,{keep:true});A.toast('✓ Étape '+n+' faite — prends la pièce en photo');}else A.toast('✓ Étape '+n+' faite');}
function undoStep(id){const f=findStep(id);if(!f)return;const m=marksOf()[id];if(!m)return;if(!(isMgr()||(m.byKey&&m.byKey===myKey()))){A.toast('Réservé à l\'encadrement ou à celui qui a coché');return;}if(!delRec(m.id))return;hyRerender();A.toast('Étape remise « à faire »');}
function moveStep(id,dir){const f=findStep(id);if(!f)return;const j=f.i+dir;if(j<0||j>=f.list.length)return;f.list.splice(f.i,1);f.list.splice(j,0,f.s);A.saveHydro();hyRerender();}
function delStep(id){const f=findStep(id);if(!f)return;f.list.splice(f.i,1);A.saveHydro();hyRerender();}
function addStepModal(type){const {h,H}=hyCtx();if(!h||!H||!MOD_T[type])return;const prest=MS.prest;if(!prest){A.toast('Coche d\'abord une prestation');return;}const pts=sessionPoints().filter(p=>!p.absent);const isV=['ouvrir','fermer','verifier'].includes(type);const list=(isV?pts.filter(p=>p.nature==='vanne'):type==='purge'?pts.filter(p=>p.nature==='purge'||p.nature==='vidange'):[]).sort(byLinePk);
  const tronSel=all=>`<label class="f">Tronçon</label><select class="f" id="pm-tron">${all?'<option value="">Tout le réseau</option>':''}${H.troncons.map(t=>`<option value="${t.idx}" ${MS.tron===t.idx?'selected':''}>Tronçon ${t.idx+1} — ${esc(t.lines.map(id=>(A.state.lines[id]||{}).name||id).slice(0,2).join(' + '))}</option>`).join('')}</select>`;
  let body='';
  if(isV||type==='purge')body=(list.length?`<label class="f">${isV?'Quelle vanne ?':'Quel té ?'}</label><div class="pt-pick">${list.map(p=>`<button class="chip" data-pm-pt="${esc(p.key)}">${p.glyph} ${esc(labelShort(p))} · ${esc(p.lineName)}</button>`).join('')}</div>`:'<div class="warnbox">Aucune pièce de ce type sur le tracé.</div>')+tronSel(true);
  else if(type==='op')body=`<label class="f">Opération</label><div class="pt-pick">${MOD_OPS.map(o=>`<button class="chip" data-pm-op="${o[0]}">${esc(o[1])}</button>`).join('')}</div>${tronSel(false)}<label class="f">Durée ou consigne (facultatif)</label><input class="f" id="pm-note" placeholder="ex. 20 min à 1 m/s · 6 bar pendant 2 h">`;
  else body=`<label class="f">Note</label><textarea class="f" id="pm-note" placeholder="ex. prévenir l'exploitant avant d'ouvrir"></textarea>${tronSel(true)}`;
  const lab=type==='op'?'Opération sur un tronçon':type==='note'?'Note libre':type==='purge'?'Purger / vidanger':MOD_T[type][0]+' une vanne';
  A.openModal(`<h3 style="margin-top:0">＋ ${MOD_T[type][1]} ${esc(lab)} <span class="dim" style="font-weight:400;font-size:12px">· ${esc(PREST_LABEL[prest]||prest)}</span></h3>${body}<div class="actions"><button class="btn primary block" id="pm-ok">Ajouter l'étape</button><button class="btn block" data-close>Annuler</button></div>`);
  const sel={pt:null,op:null};const M=document.getElementById('modal');
  M.querySelectorAll('[data-pm-pt]').forEach(b=>b.onclick=()=>{sel.pt=b.dataset.pmPt;M.querySelectorAll('[data-pm-pt]').forEach(x=>x.classList.toggle('on',x===b));});
  M.querySelectorAll('[data-pm-op]').forEach(b=>b.onclick=()=>{sel.op=b.dataset.pmOp;M.querySelectorAll('[data-pm-op]').forEach(x=>x.classList.toggle('on',x===b));});
  const ok=document.getElementById('pm-ok');if(ok)ok.onclick=()=>{const tr=document.getElementById('pm-tron');const tron=tr&&tr.value!==''?+tr.value:null;const ne=document.getElementById('pm-note');const note=ne?ne.value.trim():'';
    if((isV||type==='purge')&&!sel.pt){A.toast(isV?'Choisis la vanne':'Choisis le té');return;}if(type==='op'&&!sel.op){A.toast('Choisis l\'opération');return;}if(type==='op'&&tron==null){A.toast('Choisis le tronçon');return;}if(type==='note'&&!note){A.toast('Écris la note');return;}
    const P=sel.pt?pointByKey(sel.pt):null;addStep(prest,{type,pt:sel.pt,tron,op:sel.op,label:P?labelShort(P)+' · '+P.lineName:(type==='note'?note.slice(0,80):''),note});A.closeModal();A.toast('Étape ajoutée');};}
function dupModal(){const {h,H}=hyCtx();if(!h||!H||MS.tron==null)return;const src=MS.tron;const steps=modOf(h,MS.prest,false).filter(s=>s.tron===src);if(!steps.length){A.toast('Aucune étape propre au tronçon '+(src+1));return;}const others=H.troncons.filter(t=>t.idx!==src);if(!others.length){A.toast('Un seul tronçon');return;}
  A.openModal(`<h3 style="margin-top:0">⧉ Dupliquer les ${steps.length} étape${steps.length>1?'s':''} du tronçon ${src+1}</h3><label class="f">Vers le tronçon</label><select class="f" id="pm-tron">${others.map(t=>`<option value="${t.idx}">Tronçon ${t.idx+1} — ${esc(t.lines.map(id=>(A.state.lines[id]||{}).name||id).slice(0,2).join(' + '))}</option>`).join('')}</select><div class="hint">Copiées « à faire » ; les vannes restent celles du tronçon ${src+1} : remplace-les si l'autre tronçon a les siennes.</div><div class="actions"><button class="btn primary block" id="pm-ok">Dupliquer</button><button class="btn block" data-close>Annuler</button></div>`);
  const ok=document.getElementById('pm-ok');if(ok)ok.onclick=()=>{const t=+document.getElementById('pm-tron').value;const list=modOf(h,MS.prest,true);steps.forEach(s=>{list.push(Object.assign({},s,{id:'m'+uid(),tron:t}));});A.closeModal();MS.tron=t;A.saveHydro();hyRerender();A.toast(steps.length+' étape'+(steps.length>1?'s':'')+' copiée'+(steps.length>1?'s':'')+' sur le tronçon '+(t+1));};}
/* impression A4 (charte SCR) : chantier, prestation, tronçons colorés, étapes numérotées (vanne / ligne / PK), cases fait / qui / quand */
function modopPrintHTML(prest){const {h,H}=hyCtx();if(!h||!H)return '';const NET=A.net();const steps=modOf(h,prest,false);const marks=marksOf();const tron=MS.tron;const shown=tron==null?steps:steps.filter(s=>s.tron==null||s.tron===tron);
  const trs=`<div class="kpi">${H.troncons.map(t=>`<div style="border-left:6px solid ${tcol(t.idx)}"><b>T${t.idx+1}</b>${esc(t.lines.map(id=>(A.state.lines[id]||{}).name||id).join(' + '))} · ${fmt(Math.round(t.lenA))} m</div>`).join('')}</div>`;
  const rows=shown.map((s,i)=>{const P=s.pt?pointByKey(s.pt):null;return `<tr><td class="n"><b>${i+1}</b></td><td>${esc(stepTitle(s,H))}${s.note&&s.type!=='note'?'<br><span class="dim">'+esc(s.note)+'</span>':''}</td><td>${P?esc(P.lineName)+' · PK '+fmt(P.pk)+(P.etatRec?' · '+esc(etatTxt(P.etatRec))+' le '+esc(dhm(P.etatRec.at)):''):(s.tron!=null?'<span style="color:'+tcol(s.tron)+';font-weight:700">T'+(s.tron+1)+'</span>':'')}</td><td style="text-align:center;font-size:16px">${marks[s.id]?'☑':'☐'}</td><td>${marks[s.id]?esc(marks[s.id].byName||''):''}</td><td>${marks[s.id]?esc(dhm(marks[s.id].at)):''}</td></tr>`;}).join('');
  const body=`${trs}<h2>Étapes — ${esc(PREST_LABEL[prest]||prest)}${tron!=null?' · tronçon '+(tron+1):''}</h2><table><thead><tr><th style="width:28px">N°</th><th>Étape</th><th>Vanne / tronçon · ligne · PK</th><th style="width:44px">Fait</th><th style="width:120px">Qui</th><th style="width:90px">Quand</th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="dim">aucune étape</td></tr>'}</tbody></table><div class="card soft" style="margin-top:14px">À chaque étape cochée dans l'appli, l'état de la vanne (ouverte / fermée) est enregistré avec sa date, son auteur et la photo ; ces constats sont dans le DOE (équipements et points de contrôle).</div>`;
  return docHTML({title:'Mode opératoire — '+(PREST_LABEL[prest]||prest)+' — '+(NET.name||''),h1:'Mode opératoire — '+(PREST_LABEL[prest]||prest),kicker:'Hydraulique · mode opératoire',sub:esc(NET.name||''),meta:[['Chantier',esc(NET.name||'')],['Prestation',esc(PREST_LABEL[prest]||prest)],['Étapes',shown.length],['Édité le',new Date().toLocaleDateString('fr-FR')]],body,footLeft:esc(NET.name||'')});}
function printModop(prest){const html=modopPrintHTML(prest);if(!html)return;const w=window.open('about:blank');if(!w){A.toast('Autorise l\'ouverture de fenêtres pour l\'impression');return;}w.document.write(html);w.document.close();}
/* DOE : les modes opératoires exécutés (toutes les étapes, faites ou non, qui / quand) */
function modopDoeHTML(){try{const net=A.net();const m=(net&&net.hydro&&net.hydro.modop)||{};const L=PRESTS.filter(k=>(m[k]||[]).length);if(!L.length)return '';const marks=marksOf();
    return `<h3 style="margin:12px 0 4px">Modes opératoires hydrauliques</h3>`+L.map(k=>{const steps=m[k];const d=steps.filter(s=>marks[s.id]).length;return `<h4 class="ptp">${esc(PREST_LABEL[k]||k)} — ${d} / ${steps.length} étape${steps.length>1?'s':''} faite${d>1?'s':''}</h4><table><thead><tr><th style="width:28px">N°</th><th>Étape</th><th>Tronçon</th><th>Fait par</th><th>Le</th></tr></thead><tbody>${steps.map((s,i)=>`<tr><td class="n">${i+1}</td><td>${esc(stepTitle(s,null))}${s.note&&s.type!=='note'?' <span class="dim">— '+esc(s.note)+'</span>':''}</td><td>${s.tron!=null?'T'+(s.tron+1):''}</td><td>${marks[s.id]?esc(marks[s.id].byName||''):'<span class="dim">—</span>'}</td><td>${marks[s.id]?esc(dhm(marks[s.id].at)):''}</td></tr>`).join('')}</tbody></table>`;}).join('');}catch(e){console.warn('modop DOE',e);return '';}}
/* ── checklist DASH du Bureau (espace.js) : net = chantier (fiches de session _lines si ouvert, sinon lignes brutes) ── */
export function ptseqDash(net){try{if(!net||!A)return {k:'off',v:'—',s:'',n:0};const lines=net._lines?Object.values(net._lines):(net.lines||[]);const pts=pointsOf(net.id,lines);const C=ptseqCounts(pts);
    if(!C.n)return {k:'off',v:'aucun point sur le tracé',s:'',n:0};if(!C.nCons)return {k:'off',v:C.n+' point'+(C.n>1?'s':'')+' · aucun constat',s:'',n:0}; /* jamais obligatoire : sans constat, rien ne s'allume */
    return {k:(C.vSansEtat||C.sansPhoto)?'warn':'ok',v:C.n+' point'+(C.n>1?'s':'')+' · '+C.nPhotos+' photo'+(C.nPhotos>1?'s':''),s:[C.vSansEtat?C.vSansEtat+' vanne'+(C.vSansEtat>1?'s':'')+' sans état':'',C.sansPhoto?C.sansPhoto+' point'+(C.sansPhoto>1?'s':'')+' sans photo':''].filter(Boolean).join(' · '),n:C.vSansEtat+C.sansPhoto};}catch(e){console.warn('points',e);return {k:'off',v:'—',s:'',n:0};}}
/* ── DOE : points documentés (au moins un constat autre que « suivi », ou une photo), constats du plus ancien au plus récent ── */
export function ptseqDoeData(siteId){const pts=pointsOf(siteId,Object.values(A.state.lines||{})).filter(p=>p.recs.some(r=>r.ctx!=='suivi'||(r.photos||[]).length));
  return pts.map(p=>{let k=0;const cons=p.recs.slice().reverse().map(r=>({id:r.id,ctx:r.ctx,ctxLabel:ctxOf(r.ctx)[1],etat:r.etat||null,note:r.note||'',by:r.byName||r.by||'',at:r.at||null,photos:(r.photos||[]).filter(x=>x&&typeof x.u==='string').map(x=>({src:x.u,w:x.w||null,h:x.h||null,file:`${slug(labelShort(p))}_${slug(r.ctx||'autre')}_${r.at?String(r.at).slice(0,10):'sans-date'}_${++k}.jpg`}))}));
    const er=p.etatRec;return {key:p.key,line:p.line,lineName:p.lineName,nature:p.nature,natureLabel:natLabel(p),label:labelOf(p),short:labelShort(p),pk:p.pk,dn:p.dn||null,absent:!!p.absent,etat:er?er.etat:null,etatLabel:er?(er.etat==='ouverte'?'Ouverte':'Fermée'):'',etatAt:er?er.at:null,etatBy:er?(er.byName||''):'',constats:cons,nPhotos:cons.reduce((s,c)=>s+c.photos.length,0)};})
    .sort((a,b)=>a.lineName.localeCompare(b.lineName,'fr',{numeric:true})||a.pk-b.pk);}
/* section « Équipements et points de contrôle » du carnet (o.rel(photo, point) = chemin dans le dossier, sinon adresse en ligne) */
export function ptseqDoeSection(D,o){o=o||{};const pts=D.points||[];const modH=((()=>{try{return A.modop&&A.modop()?A.modop().doe():'';}catch(e){return '';}})())+modopDoeHTML();if(!pts.length&&!modH)return '';const rel=o.rel||(p=>p.src);const nPh=pts.reduce((s,p)=>s+p.nPhotos,0);const byLine={};pts.forEach(p=>{(byLine[p.lineName]=byLine[p.lineName]||[]).push(p);});
  let h=`<section class="pg brk"><style>.ptg{display:flex;flex-wrap:wrap;gap:5px;margin:4px 0 10px}.ptg figure{margin:0;width:60mm;page-break-inside:avoid}.ptg img{width:60mm;height:45mm;object-fit:cover;border:1px solid #ccc;display:block;background:#eee}.ptg figcaption{font-size:9px;color:#555;margin-top:2px}.ptg .ko{width:60mm;height:45mm;box-sizing:border-box;padding:6px;font-size:9px;color:#8a3b00;background:#fdf0ea;border:1px dashed #e8501c;display:flex;align-items:center}h4.ptp{margin:8px 0 2px;font-size:11px}</style>
   <h2>Équipements et points de contrôle <span class="dim" style="font-weight:400;font-size:12px">· ${pts.length} point${pts.length>1?'s':''} documenté${pts.length>1?'s':''} · ${nPh} photo${nPh>1?'s':''}</span></h2>
   <div class="muted" style="max-width:190mm">Vannes, purges, vidanges, sous-stations et raccordements : état final (ouverte / fermée) avec sa date et son auteur, puis les constats photographiés dans l'ordre (contexte, date, auteur, note) — saisis sur le chantier, dans l'appli. Les photos sont dans le dossier Photos, par ligne, sous-dossier « Points ».</div>`;
  Object.keys(byLine).forEach(ln=>{const L=byLine[ln];h+=`<h3 style="margin:10px 0 4px">${esc(ln)}</h3><table><thead><tr><th>Point</th><th class="n">PK (m)</th><th>DN</th><th>État final</th><th>Constats</th><th class="n">Photos</th></tr></thead><tbody>${L.map(p=>`<tr><td><b>${esc(p.natureLabel)}</b>${p.absent?' <span class="hot">(pièce absente du tracé actuel)</span>':''}</td><td class="n">${fmt(p.pk)}</td><td>${esc(p.dn||'')}</td><td>${p.etat?`<b>${p.etat==='ouverte'?'Ouverte':'Fermée'}</b><br><span class="dim">${esc(dFR(p.etatAt))}${p.etatBy?' · '+esc(p.etatBy):''}</span>`:'—'}</td><td>${p.constats.map(c=>esc(c.ctxLabel)+' '+esc(dFR(c.at))).join(' · ')}</td><td class="n">${p.nPhotos||''}</td></tr>`).join('')}</tbody></table>`;
    L.forEach(p=>{if(!p.nPhotos)return;h+=`<h4 class="ptp">${esc(p.short)}</h4><div class="ptg">${p.constats.map(c=>c.photos.map(ph=>`<figure><img src="${esc(rel(ph,p))}" data-abs="${esc(ph.src)}" loading="lazy" onerror="if(this.dataset.abs&&!this.dataset.tried){this.dataset.tried='1';this.src=this.dataset.abs;}else this.outerHTML='<div class=ko>photo introuvable (dossier décompressé ? connexion ?)</div>'" alt=""><figcaption>${esc(c.ctxLabel)}${c.etat?' ('+(c.etat==='ouverte'?'ouverte':'fermée')+')':''} · ${esc(dFR(c.at))} · ${esc(c.by)}${c.note?' — '+esc(c.note):''}</figcaption></figure>`).join('')).join('')}</div>`;});});
  return h+modH+'</section>';}
/* galerie du dossier Photos (02_Photos/index.html) : un bloc par point, après les soudures */
export function ptseqGallerySection(D,o){o=o||{};const pts=(D.points||[]).filter(p=>p.nPhotos);if(!pts.length)return '';const rel=o.rel||(p=>p.src);
  return pts.map(p=>`<div class="w" data-k="${esc((p.label+' POINT').toUpperCase())}"><h3>📍 ${esc(p.short)} <span>${esc(p.lineName)}${p.etat?' · '+(p.etat==='ouverte'?'ouverte':'fermée')+' le '+esc(dFR(p.etatAt)):''}</span></h3><div class="ph">${p.constats.map(c=>c.photos.map(ph=>`<figure><a href="${esc(rel(ph,p))}" target="_blank"><img src="${esc(rel(ph,p))}" data-abs="${esc(ph.src)}" loading="lazy" onerror="phKo(this)" alt=""></a><figcaption>${esc(c.ctxLabel)} · ${esc(dFR(c.at))} · ${esc(c.by)}${c.note?' — '+esc(c.note):''}</figcaption></figure>`).join('')).join('')}</div></div>`).join('');}
/* ── branchement ── */
export function ptseqOnSite(id){if(!id||id==='__vide')return;regLoad('pteq').then(()=>{pump();try{ptseqOverlay();}catch(e){}if(A.state.tab==='points')ptseqRender();}).catch(e=>console.warn(e));}
function injectTab(){const tb=document.getElementById('tabbar');const cont=document.querySelector('.view')?.parentElement;if(!tb||!cont)return;
  if(!tb.querySelector('[data-tab="points"]')){const b=document.createElement('button');b.dataset.tab='points';b.textContent='📍 Points';tb.insertBefore(b,tb.querySelector('[data-tab="liste"]')||tb.querySelector('[data-tab="recap"]')||tb.querySelector('[data-tab="export"]'));}
  if(!document.getElementById('view-points')){const v=document.createElement('section');v.className='view';v.id='view-points';v.innerHTML='<div class="pad" id="points"></div>';cont.appendChild(v);}
  const mk=document.getElementById('markers');if(mk&&!document.getElementById('ptG')){const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='ptG';mk.appendChild(g);}}
function onSheetClick(e){const b=e.target.closest('[data-pact]');if(!b||!A)return;const a=b.dataset.pact;const S=A.state;e.preventDefault();e.stopPropagation();
  if(a==='openpt'){openPoint(b.dataset.pt);return;}if(a==='follow'){follow(b.dataset.line,b.dataset.cond,+b.dataset.i);return;}if(a==='unfollow'){unfollow(b.dataset.pt);return;}
  if(a==='open'){openPoint(b.dataset.pt);return;}if(a==='goto'){gotoPoint(b.dataset.pt);return;}if(a==='filter'){S.ptFilter=b.dataset.v;ptseqRender();return;}
  if(a==='list'){A.closeSheet();S.tab='points';A.renderAll();return;}if(a==='piece'){const s=S.sel;if(s&&s.kind==='pt')A.openEl(s.line,s.cond||'A',s.i);return;}
  if(a==='etat'){if(!canWrite()){A.toast('Lecture seule');return;}setEtat(b.dataset.v);return;}if(a==='noask'){PS.ask=null;rerenderSheet();return;}
  if(a==='form'){PS.form=true;rerenderSheet();return;}if(a==='ctx'){PS.ctx=b.dataset.v;rerenderSheet();return;}if(a==='cancel'){resetPS();rerenderSheet();return;}if(a==='save'){saveForm();return;}
  if(a==='unpend'){PS.pending.splice(+b.dataset.k,1);rerenderSheet();return;}if(a==='view'){viewPhoto(b.dataset.id,+b.dataset.k);return;}
  if(a==='del'){const r=regGet('pteq',b.dataset.id);if(!r)return;if(!confirm('Retirer ce constat ('+ctxOf(r.ctx)[1]+' du '+dhm(r.at)+') ?'))return;delRec(b.dataset.id);return;}
  /* mode opératoire (onglets Hydraulique et Points) */
  if(a==='h-prest'){MS.prest=b.dataset.v;hyRerender();return;}if(a==='h-tron'){MS.tron=b.dataset.v===''?null:+b.dataset.v;hyRerender();return;}if(a==='h-print'){printModop(MS.prest);return;}
  if(a==='h-done'){doStep(b.dataset.id);return;}if(a==='h-undone'){undoStep(b.dataset.id);return;}
  const edit=['h-add','h-dup','h-up','h-down','h-del','h-exec'].includes(a);if(edit&&!A.can('hydro')){A.toast('Réservé à l\'encadrement (droit « Hydro »)');return;}
  if(a==='h-add'){addStepModal(b.dataset.v);return;}if(a==='h-dup'){dupModal();return;}if(a==='h-up'){moveStep(b.dataset.id,-1);return;}if(a==='h-down'){moveStep(b.dataset.id,1);return;}if(a==='h-del'){if(!confirm('Retirer cette étape ?'))return;delStep(b.dataset.id);return;}
  if(a==='h-exec'){if(A.openHydroExecModal)A.openHydroExecModal(+b.dataset.t,b.dataset.k);return;}}
function onSheetChange(e){const inp=e.target.closest('input[data-ptph]');if(!inp||!A)return;e.stopPropagation();const files=[...inp.files];const t=inp.dataset.ptph;inp.value='';onPhotos(t,files).catch(x=>console.warn('photos',x));}
function onSheetInput(e){const ta=e.target.closest('[data-ptnote]');if(ta)PS.note=ta.value;}
export function initPtseq(api){A=api;css();try{injectTab();}catch(e){console.warn('points : onglet',e);}
  const sh=document.getElementById('sheet');if(sh){sh.addEventListener('click',onSheetClick);sh.addEventListener('change',onSheetChange);sh.addEventListener('input',onSheetInput);}
  const pv=document.getElementById('points');if(pv)pv.addEventListener('click',onSheetClick);const hv=document.getElementById('hydro');if(hv)hv.addEventListener('click',onSheetClick); /* 20/10 (PH) : vannes et mode opératoire dans l'onglet Hydraulique */
  onReg(kind=>{if(kind!=='pteq')return;const S=A.state;if(S.screen!=='site')return;try{ptseqOverlay();}catch(e){}if(S.tab==='points')ptseqRender();if(S.tab==='hydro'&&A.renderHydro)A.renderHydro();if(S.sel&&S.sel.kind==='pt')rerenderSheet();});
  onRegSent(()=>{pump();});try{window.addEventListener('online',()=>setTimeout(()=>pump(),800));}catch(e){}setInterval(()=>{if(PQ.size)pump();},45000);loadQ();
  regLoad('pteq').then(()=>pump()).catch(e=>console.warn(e)); /* miroir de l'appareil tout de suite (checklist du Bureau, hub), serveur dès la connexion (rafraîchissement léger de l'appli) ; rechargé à chaque ouverture de chantier */}
export const ptseqApi={points:()=>sessionPoints(),counts:()=>ptseqCounts(sessionPoints()),open:ptseqOpen,goto:gotoPoint,add:(key,o)=>{const P=pointByKey(key);return P?newRec(P,o||{ctx:'autre',photos:[]}):null;},etat:v=>setEtat(v),del:delRec,follow:(l,c,i)=>follow(l,c,i),pending:()=>[...PQ],pump,doe:id=>ptseqDoeData(id||A.state.siteId),dash:net=>ptseqDash(net),natureOf,keyOf,modop:{steps:k=>{const {h}=hyCtx();return h?modOf(h,k,false):[];},marks:()=>marksOf(),add:(k,st)=>addStep(k,st),done:id=>doStep(id),undo:id=>undoStep(id),view:(k,t)=>{if(k)MS.prest=k;MS.tron=t==null?null:t;},printHTML:k=>modopPrintHTML(k||MS.prest),cut:c=>ptseqCutState(c),html:()=>modopHTML({canEdit:A.can('hydro'),where:'points'})}};
